  return { code: raw.code as SshForwardErrorCode, message: raw.message, retryable: raw.retryable, ...(typeof raw.scopeId === "string" ? { scopeId: raw.scopeId } : {}), ...(typeof raw.profileId === "string" ? { profileId: raw.profileId } : {}), ...(parseWireCounter(raw.currentProfilesRevision) ? { currentProfilesRevision: parseWireCounter(raw.currentProfilesRevision)! } : {}), ...(parseWireCounter(raw.currentTrustRevision) ? { currentTrustRevision: parseWireCounter(raw.currentTrustRevision)! } : {}), ...(parseWireCounter(raw.currentScopeGeneration) ? { currentScopeGeneration: parseWireCounter(raw.currentScopeGeneration)! } : {}), ...(parseWireCounter(raw.currentGeneration) ? { currentGeneration: parseWireCounter(raw.currentGeneration)! } : {}) };
