export type SshForwardHostEvent = { type: "changed"; hint: SshForwardEventHint; snapshot?: SshForwardSnapshot };

export interface SshForwardHost {
  openClient(knownScopes: KnownScopesInput): Promise<OpenClientResult>;
  activateScope(scopeId: string | null): Promise<ScopeActivation>;
  snapshot(): Promise<SshForwardSnapshot>;
  createProfile(profile: SshForwardProfile): Promise<SshForwardSnapshot>;
  updateProfile(profileId: string, expectedGeneration: WireCounter, profile: SshForwardProfile): Promise<SshForwardSnapshot>;
  deleteProfile(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot>;
  start(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot>;
  stop(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot>;
  restart(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot>;
  listKeys(): Promise<KeyInventory>;
  approveHost(profileId: string, expectedGeneration: WireCounter, challengeId: string, algorithm: string, fingerprint: string): Promise<SshForwardSnapshot>;
  purgeScope(scopeId: string, knownScopes: KnownScopesInput): Promise<{ scopeId: string; purged: boolean }>;
  subscribe(listener: (event: SshForwardHostEvent) => void): () => void;
  dispose(): void;
}

