    void qc.cancelQueries().then(() => qc.resetQueries());

    const transport = getTransport();
    return transport.onEvent("workspace:changed", () => {
      void qc.invalidateQueries({ queryKey: ["workspace-status"] });
    });
  }, [activeProfileConnectionKey, activeProfileId, activeProfileUrl, qc]);

  return (
    <EncryptProvider>
      <AndroidChromeInputPolicyProvider>
        <BrowserRouter basename={routerBasename}>
          <AndroidChromeKeyboardNotice />
          <GlobalShortcuts />
          <TerminalNotificationToastViewport />
          <RouteDiagnostics />
          <PassphrasePrompt />
          <ServerProfileGuard>
            <AuthGuard>
              <WorkspaceGuard>
                <Routes>
                  <Route
                    path="/"
                    element={
                      <ErrorBoundary>
                        <Suspense fallback={LOADING_FALLBACK}>
                          <DashboardPage />
                        </Suspense>
                      </ErrorBoundary>
                    }
                  />
                  <Route
                    path="/workspace"
                    element={
                      <ErrorBoundary>
                        <Suspense fallback={LOADING_FALLBACK}>
                          <WorkspacePage />
                        </Suspense>
                      </ErrorBoundary>
                    }
                  />
                  {/* Backward-compat redirects — preserve search params for deep-links */}
                  <Route
                    path="/terminals"
                    element={<LegacyRedirect to="/workspace" />}
                  />
                  <Route
                    path="/ide"
                    element={<LegacyRedirect to="/workspace" />}
                  />
                  <Route
                    path="/git"
                    element={
                      <ErrorBoundary>
                        <Suspense fallback={LOADING_FALLBACK}>
                          <GitPage />
                        </Suspense>
                      </ErrorBoundary>
                    }
                  />
                  <Route
                    path="/settings"
                    element={
                      <ErrorBoundary>
                        <Suspense fallback={LOADING_FALLBACK}>
                          <SettingsPage />
                        </Suspense>
                      </ErrorBoundary>
                    }
                  />
                  <Route
                    path="/agent-store"
                    element={
                      <ErrorBoundary>
                        <Suspense fallback={LOADING_FALLBACK}>
                          <AgentStorePage />
                        </Suspense>
                      </ErrorBoundary>
                    }
                  />
                  <Route
                    path="/usage"
                    element={
                      <ErrorBoundary>
                        <Suspense fallback={LOADING_FALLBACK}>
                          <UsagePage />
                        </Suspense>
                      </ErrorBoundary>
                    }
                  />
                </Routes>
              </WorkspaceGuard>
            </AuthGuard>
          </ServerProfileGuard>
        </BrowserRouter>
      </AndroidChromeInputPolicyProvider>
    </EncryptProvider>
  );
}

