// @vitest-environment jsdom
import * as React from "react";
import { act } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, describe, expect, it, vi } from "vitest";
import { SshForwardHostProvider } from "@/contexts/SshForwardHostContext.js";
import { useSshForward } from "./use-ssh-forward.js";
import type { SshForwardHost, SshForwardHostEvent } from "@/lib/ssh-forward-host.js";

const context = { desktopInstanceId: "11111111-1111-4111-8111-111111111111", managerSessionId: "22222222-2222-4222-8222-222222222222", clientEpoch: "1" as any };
const snapshot = { context, activationToken: "1", scopeId: "33333333-3333-4333-8333-333333333333", scopeGeneration: "1", profilesRevision: "1", trustRevision: "1", profiles: [], runtimes: [], hostKeyChallenges: [] } as any;
let root: Root | null = null;
afterEach(() => { act(() => root?.unmount()); root = null; });

describe("useSshForward", () => {
  it("refreshes only hints matching the current context, token, and scope", async () => {
    let listener!: (event: SshForwardHostEvent) => void;
    const host = { snapshot: vi.fn().mockResolvedValue(snapshot), subscribe: vi.fn((next) => { listener = next; return () => {}; }) } as unknown as SshForwardHost;
    const container = document.createElement("div"); root = createRoot(container);
    function Harness() { const state = useSshForward(); React.useEffect(() => { void state.refresh(); }, [state.refresh]); return null; }
    await act(async () => root?.render(<SshForwardHostProvider host={host} environment={{ kind: "nativeDesktop" }}><Harness /></SshForwardHostProvider>));
    await act(async () => {}); host.snapshot.mockClear();
    const hint = { ...snapshot, ...context, clientEpoch: "2", reason: "profilesChanged" } as any;
    await act(async () => listener({ type: "changed", hint }));
    expect(host.snapshot).not.toHaveBeenCalled();
    await act(async () => listener({ type: "changed", hint: { ...hint, clientEpoch: "1" } }));
    expect(host.snapshot).toHaveBeenCalledOnce();
  });
});

